import {CreditCard} from 'lucide-react';
const wechat = 'data:image/png;base64,';
const alipay = 'data:image/png;base64,';
const unionpay = 'data:image/png;base64,';

const logos:Record<string,string>={wechat,alipay,unionpay};
export function PaymentBrand({name}:{name:string}){
 if(logos[name])return <img className="payment-brand" src={logos[name]} alt="" aria-hidden="true"/>;
 return <CreditCard className="payment-brand" aria-hidden="true"/>;
}
